-- 09 / 02 — SYNC (writes UAT-ISV). NOT RUN YET. UAT-ISV ONLY — never UAT, never Production.
-- Run 00_precheck_readonly.sql and 01_backup.sql first.
--   psql "<uat-isv conn>" -v ON_ERROR_STOP=1 -f 02_sync.sql                 -- part A + part B
--   psql "<uat-isv conn>" -v ON_ERROR_STOP=1 -v skip_duty=1 -f 02_sync.sql  -- part A only
-- Idempotent: re-running inserts nothing / updates nothing.
\set ON_ERROR_STOP on

-- Refuse to run anywhere except UAT-ISV (Cloud SQL insurverse-uat-isv-db: public 136.85.102.224 / private 10.242.0.6)
-- and refuse to run without the backup.
SELECT (host(inet_server_addr()) IN ('136.85.102.224','10.242.0.6')) AS is_uatisv,
       (to_regclass('insurverse._bk09_imp_price_premium') IS NOT NULL
        AND to_regclass('insurverse._bk09_sys_param') IS NOT NULL) AS backup_present \gset
\if :is_uatisv
\else
  \echo 'ABORT: server is not the UAT-ISV Cloud SQL instance. This job must not run on UAT/Prod.'
  \quit
\endif
\if :backup_present
\else
  \echo 'ABORT: run 01_backup.sql first.'
  \quit
\endif

