), ins AS (
  INSERT INTO insurverse."Imp_Price_Premium"
  SELECT s.* FROM src s
  WHERE NOT EXISTS (
    SELECT 1 FROM insurverse."Imp_Price_Premium" x
    WHERE x.is_active
      AND x."Brand" = s."Brand" AND x."Model" = s."Model" AND x."Year" = s."Year"
      AND x."Doors" = s."Doors" AND x."CC" = s."CC" AND x."Usage" = s."Usage"
      AND x."Type" = s."Type" AND x."GarageType" = s."GarageType"
      AND x.driver_behavior IS NOT DISTINCT FROM s.driver_behavior)
  RETURNING 1
)
SELECT count(*) AS ipp_inserted FROM ins;   -- expected 36 on the first run, 0 on re-runs

-- post-condition: no duplicate active key for these cars (must return 0 rows)
SELECT "Brand","Model","Year","Doors","CC","Usage","Type","GarageType",driver_behavior, count(*)
FROM insurverse."Imp_Price_Premium" WHERE is_active
  AND ("Brand","Model","Year") IN (('Toyota','Yaris','2024'),('Mitsubishi','Attrage','2021'),('Jeep','Wrangler','2010'))
GROUP BY 1,2,3,4,5,6,7,8,9 HAVING count(*) > 1;
COMMIT;

-- ============================================================================
-- PART B — sys_param purchase/duty/duty_per: 0.004 (UAT-ISV) → 0.4 (UAT)
--   Callers compute duty = CEIL(prem * duty_per / 100): go-echo-pa-service, go-echo-home-service,
--   premium-service ta.controller, DB fn_policy_renewal. With 0.004 every duty is 1 THB.
--   PA smoke 2413.35 prem: duty 1 → 2414.35 (UAT-ISV) vs duty 10 → 2423.35 (UAT)
--   HI smoke  892.00 prem: duty 1, vat 62.51 → 955.51 vs duty 4, vat 62.72 → 958.72
--   BUSINESS DECISION: confirm 0.4 (= 0.4 % stamp duty) is the intended value before running; skip with -v skip_duty=1.
-- ============================================================================
\if :{?skip_duty}
  \echo 'PART B skipped (skip_duty set)'
\else
BEGIN;
UPDATE insurverse.sys_param
   SET para_value = 0.400000,
       para_str   = COALESCE(para_str, 'Duty'),
       update_date = now(),
       update_by   = 'deploy_job_09'
 WHERE dom_code='purchase' AND sub_dom_code='duty' AND para_code='duty_per'
   AND para_value IS DISTINCT FROM 0.400000;          -- expected UPDATE 1 first run, UPDATE 0 re-runs
SELECT para_value FROM insurverse.sys_param WHERE dom_code='purchase' AND sub_dom_code='duty' AND para_code='duty_per';
COMMIT;
\endif

-- premium-service caches loadPremium for 60 s (node-cache) — wait 1 min or restart the pod before re-testing.
